-- =============================================================================
-- Fix first: creating "Pivot Templates" below triggers the same
-- "auto-admin" trigger that fires when someone creates a real club through
-- the app. But here, there's no logged-in user (we're running this
-- directly in the SQL Editor), so auth.uid() is null -- and the trigger
-- was trying to insert a membership with a null user_id, which fails.
-- This makes the trigger skip that step when there's no real user,
-- without changing anything for the normal app flow.
-- =============================================================================
create or replace function public.handle_new_organization()
returns trigger as $$
begin
  if auth.uid() is not null then
    insert into public.memberships (organization_id, user_id, role, status)
    values (new.id, auth.uid(), 'admin', 'active');
  end if;
  return new;
end;
$$ language plpgsql security definer;

-- =============================================================================
-- Pivot Cloud — Seed: import the desktop app's 56 real exercises as shared templates
-- =============================================================================
-- Run in Supabase: SQL Editor → New query → paste → Run.
--
-- Creates a dedicated 'Pivot Templates' organization (not a real club --
-- just an owner for shared starter content) and imports every exercise
-- from the desktop app's data/exercises/*.json, fully translated to
-- English (name, tags, objectives, description, variants, and the
-- category/age/material lists), marked as shared so every club can see
-- them immediately.
-- =============================================================================

insert into public.organizations (id, name, is_active)
values ('00000000-0000-0000-0000-000000000001', 'Pivot Templates', true)
on conflict (id) do nothing;

insert into public.exercises
  (organization_id, number, name, favorite, difficulty, age, categories, material, tags, objectives, description, variants, diagram, is_shared)
values
  ('00000000-0000-0000-0000-000000000001', 1, 'Hello', false, 1, ARRAY['U8']::text[], ARRAY['Warm-up','Dribble','Fun']::text[], ARRAY['Balls']::text[], ARRAY['Heads up','Introduction']::text[], ARRAY['Dribble without looking','Keep your head up']::text[], 'Each player moves freely, dribbling within a marked area. Every time two players cross paths, they greet each other by saying Hello, shake hands, and introduce themselves by first name, all while keeping control of their ball. The goal is to encourage players to keep their head up, watch their surroundings, and control their dribble without looking at the ball.', 'Greet with left/right hand; Rock-Paper-Scissors; sit down while dribbling; touch a foot; switch hands; say your country; touch the baseline.', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 2, 'Robots', false, 1, ARRAY['U8']::text[], ARRAY['Dribble','Fun']::text[], ARRAY['Balls']::text[], ARRAY['Imitation','Creativity']::text[], ARRAY['Keep your head up','Dribble without looking','Discover different ways to dribble']::text[], 'Each player moves freely around the gym with a ball. Players copy the coach''s actions exactly. The coach shows different ways to dribble: right hand, left hand, finger, elbow, seated, high dribbles, low dribbles. Players must always watch the coach so they dribble without looking at their own ball.', 'Standing still or moving; touch a line; add jumps; use different body parts; let a player invent a dribble.', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 3, 'Train and wagons', false, 2, ARRAY['U8','U10']::text[], ARRAY['Dribble','Fun']::text[], ARRAY['Balls']::text[], ARRAY['Observation','Adaptation']::text[], ARRAY['Dribble without looking','Keep your head up','Adapt to the locomotive']::text[], 'The group is split into three or four trains, depending on the number of players. Groups of four or five players work best. The first player is the locomotive and the others are the wagons. The locomotive freely chooses how to dribble: right hand, left hand, hand changes, high dribble, low dribble, seated, or any other variation, without shooting. All the wagons copy the locomotive''s actions while staying in motion. On the coach''s signal, the last wagon becomes the new locomotive and invents new actions.', 'Use specific lines on the court; limit the play area; add changes of direction; finish the sequence with a shot; let each new locomotive invent a new way to dribble.', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 4, 'Frozen wolf', false, 1, ARRAY['U8']::text[], ARRAY['Dribble','Fun']::text[], ARRAY['Balls','Cones','Mats']::text[], ARRAY['Chase','Speed']::text[], ARRAY['Dribble with head up','Look around','Dribble fast']::text[], 'All players have a ball and move within an area marked by cones. Two or three players are designated as wolves. The wolves must tag the sheep, while the sheep must keep their head up, dribble, and stay away from the wolves without leaving the area. When a sheep is tagged, it stays frozen until another player frees it by passing between its legs while keeping control of their own ball.', '"Hospital" wolf with mats; require the weak-hand dribble; increase or decrease the number of wolves; shrink or enlarge the play area.', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 5, 'The cars', false, 1, ARRAY['U8']::text[], ARRAY['Dribble','Fun']::text[], ARRAY['Balls','Cones']::text[], ARRAY['Stops','Traffic']::text[], ARRAY['1-count stop','2-count stop','Cross from both sides','Dribble with head up']::text[], 'All players have a ball and move by dribbling only along the court lines, like cars driving on roads. As they approach an intersection, the coach calls out an instruction: a 1-count stop, a 2-count stop, or passing on the right or left. Players must follow the instruction while keeping their head up to watch others, avoid collisions, and set off again at the right moment without losing control of their ball.', 'Let players choose which side to cross on themselves; use different colored cones as traffic lights; require the weak-hand dribble.', '{"court_1": [], "court_2": [], "court_3": [], "court_4": [], "court_5": []}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 6, 'Animal carnival', false, 1, ARRAY['U8']::text[], ARRAY['Dribble','Fun']::text[], ARRAY['Balls']::text[], ARRAY['Creativity','Coordination']::text[], ARRAY['Varied dribbles','Head up']::text[], 'Each player dribbles freely with a ball. The coach calls out an animal and players imitate how it moves while dribbling. After a few examples, some kids suggest new animals for the whole group to copy. The goal is to adapt the dribble to different situations while keeping the head up.', 'Require dribbling with one hand only; add a rule with each new animal; vary the speed of movement.', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 7, 'Hunter and hares', false, 1, ARRAY['U8','U10']::text[], ARRAY['Dribble','Fun']::text[], ARRAY['Balls']::text[], ARRAY['Reading','Crossing']::text[], ARRAY['Head up','Dribble without looking','Dribble fast','Reading the game']::text[], 'One player is designated the hunter and stands on the center line. They can only move along that line and have no ball. All other players, the hares, start on a baseline with a ball. On the signal, they cross the court dribbling to the opposite baseline, never stopping their dribble or leaving the court boundaries. While crossing, the hunter tries to tag them. Any hare that is tagged immediately becomes a hunter, leaves their ball on the side, and joins the center line to help tag other players on the next crossings. The last hare remaining wins.', 'Hunters hold hands to move together; require the weak-hand dribble; vary the width of the crossing area.', '{"court_1": [], "court_2": [], "court_3": [], "court_4": [], "court_5": [{"type": "player", "x": 0.49523809523809526, "y": 0.45271464646464626, "label": "1", "color": "#141414"}, {"type": "pass", "points": [[0.5023809523809524, 0.3675505050505049], [0.4976190476190476, 0.022411616161616153]], "color": "#141414"}, {"type": "pass", "points": [[0.4976190476190476, 0.5154671717171715], [0.4976190476190476, 0.9188762626262623]], "color": "#141414"}, {"type": "player", "x": 0.04047619047619048, "y": 0.12102272727272723, "label": "2", "color": "#141414"}, {"type": "player", "x": 0.04047619047619048, "y": 0.37203282828282813, "label": "3", "color": "#141414"}, {"type": "player", "x": 0.04047619047619048, "y": 0.5647727272727271, "label": "4", "color": "#141414"}, {"type": "player", "x": 0.04523809523809524, "y": 0.8471590909090906, "label": "5", "color": "#141414"}, {"type": "arrow", "points": [[0.07857142857142857, 0.11205808080808076], [0.18095238095238095, 0.11205808080808076]], "color": "#141414"}, {"type": "arrow", "points": [[0.09047619047619047, 0.37203282828282813], [0.19285714285714287, 0.3630681818181817]], "color": "#141414"}, {"type": "arrow", "points": [[0.09761904761904762, 0.5916666666666665], [0.1761904761904762, 0.5916666666666665]], "color": "#141414"}, {"type": "arrow", "points": [[0.0880952380952381, 0.8471590909090906], [0.19523809523809524, 0.815782828282828]], "color": "#141414"}]}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 8, 'King of the dribble', false, 2, ARRAY['U8','U10']::text[], ARRAY['Dribble','Competition','Fun']::text[], ARRAY['Balls']::text[], ARRAY['Protection','Duel']::text[], ARRAY['Head up','Dribble without looking','Protect your ball','Attack the ball']::text[], 'The court is split into three zones: the two paint areas (zones 1 and 3) and the center circle (zone 2). All players start in zone 2 with a ball. The goal is to keep control of your own ball while trying to knock other players'' balls out of their zone. Players must dribble at all times. When a player knocks an opponent''s ball out without losing their own, they move up to the zone above. If their own ball goes out of the zone, they move down to the zone below. Once a player can no longer move up or down, they stay in their zone. The goal is to finish the game in the highest zone.', 'Do an exercise after each move up or down; require the weak-hand dribble; change the size of the zones.', '{"court_1": [], "court_2": [], "court_3": [], "court_4": [{"type": "zone", "x": 0.30339194102704586, "y": 0.7735294117647059, "w": 0.3820491109229467, "h": 0.21470588235294116, "color": "#141414"}, {"type": "zone", "x": 0.32024704886188177, "y": 0.008823529411764706, "w": 0.36519400308811073, "h": 0.21764705882352942, "color": "#141414"}, {"type": "zone", "x": 0.3258654181401604, "y": 0.3911764705882353, "w": 0.37081237236638936, "h": 0.19705882352941176, "color": "#141414"}, {"type": "player", "x": 0.5168899736016337, "y": 0.10588235294117647, "label": "1", "color": "#141414"}, {"type": "player", "x": 0.4944164964885192, "y": 0.49117647058823527, "label": "2", "color": "#141414"}, {"type": "player", "x": 0.483179757931962, "y": 0.8735294117647059, "label": "3", "color": "#141414"}], "court_5": []}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 9, 'The cone game', false, 1, ARRAY['U8']::text[], ARRAY['Dribble','Competition','Fun']::text[], ARRAY['Balls','Cones','Sticks']::text[], ARRAY['Reading','Speed']::text[], ARRAY['Reading the game','Head up','Dribble fast','Dribble without looking']::text[], 'Four players start in a zone marked by sticks, each with a ball. 5 or 7 cones are placed in the center. The first round can be played without a ball, then with one. Players first take all the cones from the center. After that, they can steal cones from other players. The first to get three cones on their marker wins.', 'Change the number of cones; change the number of players; require the weak-hand dribble; first round without a ball.', '{"court_1": [{"type": "zone", "x": 0.20714285714285716, "y": 0.2606988517100877, "w": 0.35714285714285715, "h": 0.4156068650450674, "color": "#141414"}, {"type": "post", "x": 0.5607142857142857, "y": 0.26447709593777013, "color": "#141414"}, {"type": "post", "x": 0.5642857142857143, "y": 0.6800839609828375, "color": "#141414"}, {"type": "post", "x": 0.2, "y": 0.6876404494382025, "color": "#141414"}, {"type": "post", "x": 0.21785714285714286, "y": 0.2606988517100877, "color": "#141414"}, {"type": "player", "x": 0.24285714285714285, "y": 0.29092480553154715, "label": "1", "color": "#141414"}, {"type": "player", "x": 0.5285714285714286, "y": 0.2947030497592296, "label": "2", "color": "#141414"}, {"type": "player", "x": 0.5285714285714286, "y": 0.6385232744783308, "label": "3", "color": "#141414"}, {"type": "player", "x": 0.225, "y": 0.6460797629336956, "label": "4", "color": "#141414"}, {"type": "cone", "x": 0.3392857142857143, "y": 0.4685022842326214, "color": "#141414"}, {"type": "cone", "x": 0.39285714285714285, "y": 0.4760587726879863, "color": "#141414"}, {"type": "cone", "x": 0.36428571428571427, "y": 0.4269415977281147, "color": "#141414"}, {"type": "cone", "x": 0.3964285714285714, "y": 0.4307198419557971, "color": "#141414"}, {"type": "cone", "x": 0.3607142857142857, "y": 0.5025064822817633, "color": "#141414"}, {"type": "cone", "x": 0.4142857142857143, "y": 0.4458328188665268, "color": "#141414"}, {"type": "cone", "x": 0.31785714285714284, "y": 0.4420545746388444, "color": "#141414"}, {"type": "cone", "x": 0.35714285714285715, "y": 0.4496110630942093, "color": "#141414"}], "court_2": [], "court_3": [], "court_4": [], "court_5": []}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 10, 'The pirates', false, 2, ARRAY['U8','U10']::text[], ARRAY['Dribble','Competition','Fun']::text[], ARRAY['Balls','Cones','Bibs']::text[], ARRAY['Attack','Defense']::text[], ARRAY['Change of speed','Head up','Dribble without looking','Double dribble']::text[], 'Two teams face off. A wide central lane, marked by cones, is the only passage between the two camps. Behind each team is a chest holding several treasures.

Before each round, each team assigns its attackers and defenders. All players dribble at all times.

Attackers cross the central lane to try to steal a treasure from the opposing chest. If they manage to grab a treasure without being tagged, they must return to their side using one of the side lanes and place the treasure in their own chest.

If an attacker is tagged before grabbing a treasure, they immediately leave the court through a side lane, return to their starting point, and start a new attempt.

At the end of the time limit, the team that brought back the most treasures wins the round. Roles are then swapped so every player gets to attack and defend.', 'Change the attacker/defender split; change the number of treasures; replace the double-dribble rule with a coordination drill or a shot.', '{"court_1": [], "court_2": [], "court_3": [], "court_4": [{"type": "arrow", "points": [[0.056183692782786274, 0.611764705882353], [0.04494695422622902, 0.48823529411764705]], "color": "#141414"}, {"type": "arrow", "points": [[0.028091846391393137, 0.7764705882352941], [0.016855107834835882, 0.6529411764705882]], "color": "#141414"}, {"type": "arrow", "points": [[0.03932858494795039, 0.9647058823529412], [0.028091846391393137, 0.8352941176470589]], "color": "#141414"}, {"type": "arrow", "points": [[0.30339194102704586, 0.37058823529411766], [0.5112716043233552, 0.9794117647058823]], "color": "#141414"}, {"type": "defender", "x": 0.30339194102704586, "y": 0.6205882352941177, "label": "X1", "color": "#141414"}, {"type": "player", "x": 0.3651940030881108, "y": 0.06470588235294118, "label": "1", "color": "#141414"}, {"type": "arrow", "points": [[0.35957563380983215, 0.09117647058823529], [0.34833889525327494, 0.29411764705882354]], "color": "#141414"}, {"type": "zone", "x": 0.15169597051352293, "y": 0.0, "w": 0.6910594212282712, "h": 1.0558823529411765, "color": "#141414"}], "court_5": []}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 11, 'Musical rings', false, 1, ARRAY['U8']::text[], ARRAY['Dribble','Fun']::text[], ARRAY['Balls','Rings']::text[], ARRAY['Music','Reaction']::text[], ARRAY['Dribble fast','Reading the game','Head up']::text[], 'Players dribble freely around rings while the music plays. At the start, there are as many rings as players. When the music stops, everyone must quickly find a ring and stand on it while keeping control of the ball. Each round, a ring is removed to create a reading and speed challenge.', 'Remove several rings at once; require the weak hand; ask for a hand change before stepping in; vary the music or round length; replace elimination with a timed technical drill.', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 12, 'Slalom', false, 2, ARRAY['U8','U10']::text[], ARRAY['Dribble','Competition']::text[], ARRAY['Balls','Cones']::text[], ARRAY['Slalom','Relay']::text[], ARRAY['Cone poles','Change of direction','Speed dribble']::text[], 'Two or three teams compete, depending on the number of players. Cones or poles are placed on the court to form two parallel lanes, with matching markers of the same color in each lane. The first player of each team starts at one end of the court. On the signal, they run the slalom, always passing outside the markers. At every change of direction, they switch hands so they dribble on the correct side and protect the ball. When they reach the other end, the next player on their team starts immediately. The team that finishes the course first wins the round.', 'Require the classic hand switch; require the between-the-legs switch; require the behind-the-back switch. Out and back.', '{"court_1": [], "court_2": [], "court_3": [], "court_4": [{"type": "arrow", "points": [[0.04494695422622902, 0.16176470588235295], [0.14607760123524433, 0.0]], "color": "#1560bd"}, {"type": "arrow", "points": [[0.19102455546147334, 0.40294117647058825], [0.04494695422622902, 0.16176470588235295]], "color": "#1560bd"}, {"type": "arrow", "points": [[0.10113064700901529, 0.6264705882352941], [0.19102455546147334, 0.40294117647058825]], "color": "#1560bd"}, {"type": "arrow", "points": [[0.16855107834835883, 0.8705882352941177], [0.10113064700901529, 0.6264705882352941]], "color": "#1560bd"}, {"type": "arrow", "points": [[0.08427553917417942, 0.9294117647058824], [0.16855107834835883, 0.8705882352941177]], "color": "#1560bd"}, {"type": "player", "x": 0.8483737610200728, "y": 0.9764705882352941, "label": "3", "color": "#1560bd"}, {"type": "player", "x": 0.46070628081884746, "y": 0.9823529411764705, "label": "2", "color": "#1560bd"}, {"type": "player", "x": 0.09551227773073667, "y": 0.9735294117647059, "label": "1", "color": "#1560bd"}, {"type": "post", "x": 0.8483737610200728, "y": 0.17941176470588235, "color": "#1560bd"}, {"type": "post", "x": 0.4663246500971261, "y": 0.17647058823529413, "color": "#1560bd"}, {"type": "post", "x": 0.12922249340040842, "y": 0.17352941176470588, "color": "#1560bd"}, {"type": "post", "x": 0.12922249340040842, "y": 0.4147058823529412, "color": "#1560bd"}, {"type": "post", "x": 0.483179757931962, "y": 0.4088235294117647, "color": "#1560bd"}, {"type": "post", "x": 0.8708472381331873, "y": 0.40588235294117647, "color": "#1560bd"}, {"type": "post", "x": 0.8315186531852369, "y": 0.6470588235294118, "color": "#1560bd"}, {"type": "post", "x": 0.483179757931962, "y": 0.638235294117647, "color": "#1560bd"}, {"type": "post", "x": 0.16855107834835883, "y": 0.6441176470588236, "color": "#1560bd"}, {"type": "post", "x": 0.10113064700901529, "y": 0.9029411764705882, "color": "#1560bd"}, {"type": "post", "x": 0.4719430193754047, "y": 0.8911764705882353, "color": "#1560bd"}, {"type": "post", "x": 0.8371370224635155, "y": 0.8970588235294118, "color": "#1560bd"}, {"type": "zone", "x": 0.6742043133934353, "y": 0.0, "w": 0.39328584947950396, "h": 0.9970588235294118, "color": "#1560bd"}, {"type": "zone", "x": 0.3258654181401604, "y": 0.0, "w": 0.34833889525327494, "h": 1.0, "color": "#c9002b"}, {"type": "zone", "x": 0.011236738556557255, "y": 0.0, "w": 0.3090103103053245, "h": 0.9941176470588236, "color": "#141414"}], "court_5": []}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 13, 'Cone relay', false, 1, ARRAY['U8','U10','U12']::text[], ARRAY['Dribble','Competition']::text[], ARRAY['Balls','Cones']::text[], ARRAY['Low dribble','Coordination']::text[], ARRAY['Low dribble','Two simultaneous actions']::text[], 'Players work in pairs. In front of each pair, four or five cones are lined up touching each other. While dribbling low, the first player picks up the last cone in the row and places it in front of the first one, then moves up to the new last cone to repeat the action. They keep this up until crossing the finish line. The cones must always stay touching each other: spacing them out or throwing them to go faster is not allowed. The first team to reach the finish line wins the round.', 'Switch hands on each way; require using the weak hand; change the number of cones.', '{"court_1": [], "court_2": [], "court_3": [], "court_4": [], "court_5": []}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 14, 'The caterpillar', false, 1, ARRAY['U8']::text[], ARRAY['Warm-up','Fun']::text[], ARRAY['Benches','Mats','Other']::text[], ARRAY['Warm-up','Cooperation']::text[], ARRAY['Getting moving','General warm-up']::text[], 'Two teams. To start, a player from the first team throws a foam ball as far as possible. As soon as the ball is thrown, all players on that team set off on a warm-up lap around the court.

Meanwhile, the other team goes to fetch the ball and forms a caterpillar: players line up single file and pass the ball hand to hand from the first to the last player, without the ball ever leaving the line. When the ball reaches the last player, that player runs to the front of the caterpillar with the ball, while everyone else moves up one spot. This repeats until the caterpillar reaches the finish line or a marker set by the coach.

The teams then swap roles.', 'Run the caterpillar twice; make the warm-up lap more complex; require a different way of moving; swap team roles each round.', '{"court_1": [], "court_2": [], "court_3": [], "court_4": [], "court_5": []}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 15, 'The garage', false, 2, '{}', ARRAY['Dribble','Shooting','Fun']::text[], ARRAY['Balls','Cones','Marker cones','Coordination ladder','Sticks','Benches','Mats','Other']::text[], '{}', ARRAY['Technical fundamentals','Variety of skills','Coordination','Reading the game']::text[], 'The whole gym is turned into a garage (see diagram 5). Players first drive around the central roundabout, dribbling with one hand. They then pick one of four roads leading to a workshop. Each workshop has a different task: flipping cones while dribbling, moving a ball with the free hand, practicing a shooting motion, finishing near the basket, playing 1-on-1, or running a coordination course followed by a shot. Once done, players return to the roundabout via the return lanes set up along the court before heading to a new workshop.', 'Add new workshops; set up a rest area ("gas station"); assign some players as traffic police to direct flow; use an upturned bench for a balance drill before shooting; change the workshops regularly.', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 16, 'Pass and combo', false, 1, ARRAY['U8']::text[], ARRAY['Warm-up']::text[], ARRAY['Balls','Marker cones']::text[], '{}', ARRAY['Calling for the ball','Getting open','Shot in motion','Avoiding collisions']::text[], 'Players move freely around the court, ball in hand, while coaches also move around. When a player makes eye contact with a coach, they call for the ball, make a pass, then immediately get open to receive the return pass. As soon as they catch it, they attack the basket of their choice, dribbling if needed, while keeping their head up to avoid collisions with other players doing the same drill. The action ends with a shot, then the player goes to find another coach.', 'Remove the pass and use different colored markers as signals. Each color corresponds to a pre-set action: attack a basket, go to a line of the same color, swap balls with a teammate, sit down while dribbling, or any other instruction chosen by the coach.', '{"court_1": [], "court_2": [], "court_3": [], "court_4": [], "court_5": []}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 17, 'Eggs in the henhouse', false, 1, ARRAY['U8','U10']::text[], ARRAY['Shooting','Fun']::text[], ARRAY['Balls','Cones']::text[], '{}', ARRAY['Shooting technique','Shooting under pressure','Team spirit']::text[], 'Form two or four teams depending on the number of players. Each team stands at a set starting point, for example center court, with a single ball. Under each basket, several cones represent "eggs." Taking turns, players dribble to the basket, take a shot, and grab their own rebound. If the shot goes in, they take a single "egg" from under the basket. They then dribble back to their team, place the egg in their nest (the starting point), hand the ball to the next player, and go to the back of the line. If the shot is missed, the player grabs the rebound, comes back without an egg, and passes the ball to the next teammate. The first team to bring all its eggs home wins.', 'Add cones or obstacles to clear before the shot; add a passer who receives and returns the ball before the finish; see diagram 1: after the pass, the passer grabs the rebound, brings the ball back to the start, and becomes the next shooter; adjust the number of eggs or the shooting distance to the group''s level.', '{"court_1": [], "court_2": [], "court_3": [], "court_4": [{"type": "cone", "x": 0.5899287742192559, "y": 0.9882352941176471, "color": "#141414"}, {"type": "cone", "x": 0.5000348657667979, "y": 0.9882352941176471, "color": "#141414"}, {"type": "cone", "x": 0.4213776958708971, "y": 0.9882352941176471, "color": "#141414"}, {"type": "cone", "x": 0.3708123723663894, "y": 0.9852941176470589, "color": "#141414"}, {"type": "cone", "x": 0.5506001892713055, "y": 0.011764705882352941, "color": "#141414"}, {"type": "cone", "x": 0.4944164964885192, "y": 0.011764705882352941, "color": "#141414"}, {"type": "cone", "x": 0.46070628081884746, "y": 0.011764705882352941, "color": "#141414"}, {"type": "cone", "x": 0.39328584947950396, "y": 0.014705882352941176, "color": "#141414"}, {"type": "zone", "x": 0.17978781690491608, "y": 0.0058823529411764705, "w": 0.6517308362803208, "h": 0.47058823529411764, "color": "#141414"}, {"type": "zone", "x": 0.20226129401803059, "y": 0.5088235294117647, "w": 0.618020620610649, "h": 0.4676470588235294, "color": "#c9002b"}, {"type": "player", "x": 0.7978084375155651, "y": 0.21764705882352942, "label": "1", "color": "#1e7a3c"}, {"type": "player", "x": 0.7022961597848284, "y": 0.7647058823529411, "label": "2", "color": "#1e7a3c"}], "court_5": [{"type": "cone", "x": 0.1738095238095238, "y": 0.022411616161616153, "color": "#141414"}, {"type": "cone", "x": 0.14523809523809525, "y": 0.022411616161616153, "color": "#141414"}, {"type": "cone", "x": 0.12142857142857143, "y": 0.017929292929292923, "color": "#141414"}, {"type": "cone", "x": 0.1, "y": 0.004482323232323231, "color": "#141414"}, {"type": "cone", "x": 0.20238095238095238, "y": 0.9681818181818178, "color": "#141414"}, {"type": "cone", "x": 0.16428571428571428, "y": 0.9592171717171714, "color": "#141414"}, {"type": "cone", "x": 0.1357142857142857, "y": 0.9592171717171714, "color": "#141414"}, {"type": "cone", "x": 0.10714285714285714, "y": 0.9636994949494946, "color": "#141414"}, {"type": "cone", "x": 0.8690476190476191, "y": 0.9816287878787875, "color": "#141414"}, {"type": "cone", "x": 0.8357142857142857, "y": 0.972664141414141, "color": "#141414"}, {"type": "cone", "x": 0.8166666666666667, "y": 0.972664141414141, "color": "#141414"}, {"type": "cone", "x": 0.7833333333333333, "y": 0.972664141414141, "color": "#141414"}, {"type": "cone", "x": 0.8904761904761904, "y": 0.04482323232323231, "color": "#141414"}, {"type": "cone", "x": 0.861904761904762, "y": 0.04930555555555553, "color": "#141414"}, {"type": "cone", "x": 0.8404761904761905, "y": 0.04034090909090907, "color": "#141414"}, {"type": "cone", "x": 0.8119047619047619, "y": 0.026893939393939383, "color": "#141414"}, {"type": "zone", "x": 0.016666666666666666, "y": 0.008964646464646462, "w": 0.47619047619047616, "h": 0.4616792929292928, "color": "#141414"}, {"type": "zone", "x": 0.5023809523809524, "y": 0.022411616161616153, "w": 0.5, "h": 0.44374999999999976, "color": "#c9002b"}, {"type": "zone", "x": 0.5023809523809524, "y": 0.4796085858585857, "w": 0.49047619047619045, "h": 0.5109848484848483, "color": "#1560bd"}, {"type": "zone", "x": -0.004761904761904762, "y": 0.4975378787878786, "w": 0.48333333333333334, "h": 0.47512626262626245, "color": "#1e7a3c"}, {"type": "player", "x": 0.3523809523809524, "y": 0.19722222222222213, "label": "1", "color": "#1e7a3c"}, {"type": "player", "x": 0.7357142857142858, "y": 0.1927398989898989, "label": "2", "color": "#1e7a3c"}, {"type": "player", "x": 0.7095238095238096, "y": 0.7306186868686866, "label": "3", "color": "#1e7a3c"}, {"type": "player", "x": 0.3261904761904762, "y": 0.7888888888888885, "label": "4", "color": "#1e7a3c"}]}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 18, 'Numbers', false, 1, ARRAY['U8','U10']::text[], ARRAY['Dribble','Shooting','Fun']::text[], ARRAY['Balls']::text[], ARRAY['Reaction','Pressure']::text[], ARRAY['Shooting technique','Shooting under pressure','Speed of execution','Concentration']::text[], 'Form two or four equal teams. Each player gets a number and every team lines up at center court, facing the basket they must attack. When the coach calls a number, the matching players immediately start dribbling toward their basket. They must control their speed, make their move, and score as quickly as possible. The first player to score wins the duel and earns a point for their team. Players then return to the center and a new number is called.', 'Eliminate the losing player of each duel, or not; require different types of finishes; start with the ball in hand or go fetch it first; adjust the distance or starting point to the group''s level.', '{"court_1": [], "court_2": [], "court_3": [], "court_4": [], "court_5": []}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 19, 'Knockout', false, 2, ARRAY['U8','U10','U12']::text[], ARRAY['Dribble','Shooting','Competition']::text[], ARRAY['Balls','Cones']::text[], ARRAY['Duel','Speed']::text[], ARRAY['Shooting under pressure','Speed dribble','Concentration','Quick execution']::text[], 'Form two teams, each in a corner of the baseline. One player from each team lines up at the start with a ball. On the coach''s signal, both players start at the same time. Cones placed at center court create two separate lanes that can''t be left. Each player must reach the opposite basket, score, grab their own rebound, return toward their starting basket, score a second time, then finish the course.', 'Give each player two lives before elimination; set a small challenge or forfeit for the eliminated player or team; adjust the shooting distance or require a specific type of finish depending on the group''s level.', '{"court_1": [], "court_2": [], "court_3": [], "court_4": [{"type": "arrow", "points": [[0.3090103103053245, 0.8970588235294118], [0.483179757931962, 0.95]], "color": "#141414"}, {"type": "arrow", "points": [[0.29215520247048865, 0.12941176470588237], [0.3090103103053245, 0.8970588235294118]], "color": "#141414"}, {"type": "arrow", "points": [[0.5168899736016337, 0.04411764705882353], [0.29215520247048865, 0.12941176470588237]], "color": "#141414"}, {"type": "arrow", "points": [[0.7303880061762216, 0.10588235294117647], [0.5168899736016337, 0.04411764705882353]], "color": "#141414"}, {"type": "arrow", "points": [[0.7528614832893361, 0.9029411764705882], [0.7303880061762216, 0.10588235294117647]], "color": "#141414"}, {"type": "player", "x": 0.14607760123524433, "y": 0.023529411764705882, "label": "2", "color": "#141414"}, {"type": "player", "x": 0.7528614832893361, "y": 0.9647058823529412, "label": "1", "color": "#141414"}, {"type": "post", "x": 0.5056532350450765, "y": 0.8852941176470588, "color": "#141414"}, {"type": "post", "x": 0.5112716043233552, "y": 0.8294117647058824, "color": "#141414"}, {"type": "post", "x": 0.5112716043233552, "y": 0.7294117647058823, "color": "#141414"}, {"type": "post", "x": 0.5112716043233552, "y": 0.6470588235294118, "color": "#141414"}, {"type": "post", "x": 0.5056532350450765, "y": 0.5617647058823529, "color": "#141414"}, {"type": "post", "x": 0.5056532350450765, "y": 0.4852941176470588, "color": "#141414"}, {"type": "post", "x": 0.5056532350450765, "y": 0.4294117647058823, "color": "#141414"}, {"type": "post", "x": 0.483179757931962, "y": 0.35, "color": "#141414"}, {"type": "post", "x": 0.48879812721024063, "y": 0.27058823529411763, "color": "#141414"}, {"type": "post", "x": 0.4944164964885192, "y": 0.2, "color": "#141414"}], "court_5": []}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 20, 'Fishing for fish', false, 1, ARRAY['U8','U10']::text[], ARRAY['Shooting']::text[], ARRAY['Balls']::text[], ARRAY['Technique','Hands']::text[], ARRAY['Hand placement','Fingers up, fingers down','Motion coordination','Shot finish']::text[], 'Each player has a ball and works in a stationary position facing the basket. The drill starts with a demonstration of the main elements of shooting technique. The ball rests on the strong hand, fingers spread, with a gap kept between the palm and the ball. The weak hand only guides the ball without pushing it. On the extension, the fingers point upward to follow through with the ball, then finish pointing down on the release. Each player has a ball and stands facing the basket. The drill starts with a demonstration of shooting technique. The ball sits on the strong hand, fingers spread, with the palm not fully touching the ball for better control. The weak hand rests on the side and only guides. Players then perform the motion slowly: the ball rises in front of the face, the legs extend, then the shooting arm fully extends. On release, the wrist snaps forward and the fingers finish pointing toward the floor, as if "catching a fish" in the basket. The goal is to reproduce a smooth, balanced motion, identical every time.', 'Work in pairs: each player throws the ball straight up doing the full motion, then tries to catch it back in the same hand without moving; vary the shooting distance or use one hand only.', '{"court_1": [], "court_2": [], "court_3": [], "court_4": [], "court_5": []}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 21, 'The basic five', false, 1, ARRAY['U8','U10']::text[], ARRAY['Shooting']::text[], ARRAY['Balls','Marker cones']::text[], ARRAY['Technique','Stations']::text[], ARRAY['Shot coordination','Hand placement','Follow-through','Shooting accuracy']::text[], 'Form four teams, each at a side basket. In front of each basket, place five upside-down markers, each holding a ball (see diagram 1). The five shooting spots are spread around the basket. On the signal, the first player of each team runs from half court to a spot still holding a ball, takes their shot focusing on quality over speed, then grabs the rebound.', 'Add obstacles before reaching the shooting spot; require a right-hand or left-hand finish; gradually move some shooting spots further out; adjust distances to the group''s level.', '{"court_1": [], "court_2": [], "court_3": [], "court_4": [], "court_5": [{"type": "ball", "x": 0.22857142857142856, "y": 0.9188762626262623, "color": "#1e7a3c"}, {"type": "ball", "x": 0.08571428571428572, "y": 0.932323232323232, "color": "#1e7a3c"}, {"type": "ball", "x": 0.0880952380952381, "y": 0.7171717171717169, "color": "#1e7a3c"}, {"type": "ball", "x": 0.15476190476190477, "y": 0.8292297979797977, "color": "#1e7a3c"}, {"type": "ball", "x": 0.21666666666666667, "y": 0.739583333333333, "color": "#1e7a3c"}, {"type": "cone", "x": 0.1595238095238095, "y": 0.8650883838383835, "color": "#1e7a3c"}, {"type": "cone", "x": 0.23333333333333334, "y": 0.9681818181818178, "color": "#1e7a3c"}, {"type": "cone", "x": 0.22380952380952382, "y": 0.7709595959595956, "color": "#1e7a3c"}, {"type": "cone", "x": 0.09523809523809523, "y": 0.7754419191919188, "color": "#1e7a3c"}, {"type": "cone", "x": 0.09047619047619047, "y": 0.9547348484848481, "color": "#1e7a3c"}, {"type": "zone", "x": 0.011904761904761904, "y": 0.5602904040404039, "w": 0.4857142857142857, "h": 0.5109848484848483, "color": "#1e7a3c"}, {"type": "zone", "x": 0.02142857142857143, "y": 0.013446969696969692, "w": 0.4666666666666667, "h": 0.4392676767676766, "color": "#1560bd"}, {"type": "zone", "x": 0.5357142857142857, "y": 0.5289141414141412, "w": 0.4166666666666667, "h": 0.5333964646464644, "color": "#c9002b"}, {"type": "zone", "x": 0.530952380952381, "y": 0.017929292929292923, "w": 0.42857142857142855, "h": 0.48857323232323213, "color": "#141414"}]}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 22, 'The shrinking cage', false, 2, ARRAY['U12','U14']::text[], ARRAY['Dribble','Defense']::text[], ARRAY['Balls']::text[], ARRAY['Ball protection','Awareness']::text[], ARRAY['Protection under pressure','Head up']::text[], 'All players dribble freely within a marked area (for example the center circle, then, on the signal, the designated zone). Everyone tries to make a teammate lose their dribble with a simple tap on the ball, while protecting their own. A player who loses control of their ball or leaves the marked area is eliminated. The last player left with their ball wins. The coach gradually shrinks the play area as the number of players decreases, to keep the difficulty up.', 'Add hoops on the floor marking off-limits zones to increase uncertainty. Require everyone to dribble with one hand only. Bring back an eliminated player after 30 seconds of push-ups.', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 23, 'The winning first step', false, 2, ARRAY['U14','U16']::text[], ARRAY['Dribble']::text[], ARRAY['Balls','Marker cones']::text[], ARRAY['First step','Footwork']::text[], ARRAY['Straight-line drive','Crossover drive','Creating separation']::text[], 'One ball per player, 6 markers fanned out facing the basket. Each player, taking turns, starts from a marker and drives toward the basket: a series of 3 straight-line first steps (the foot on the dribbling-hand side moves first), then a series of 3 crossover first steps (the opposite foot moves first). After going through all 3 spots, players switch dribbling hand and start over.', 'Add a marker just in front of the player to represent a defender to avoid. Replace the marker with a stationary defender, then with a defender who can lightly contest.', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 24, 'The 4-move combo', false, 2, ARRAY['U16','U18']::text[], ARRAY['Dribble']::text[], ARRAY['Balls','Marker cones']::text[], ARRAY['Hand change']::text[], ARRAY['4 hand changes','Fluidity']::text[], 'Players cross the width of the court in waves. On the first half, they dribble through a series of simple hand changes at each marker. On the second half, they use the behind-the-back or reverse hand change. Each crossing can end with a layup on the run to give the drill a concrete goal.', 'Require a single type of hand change for the whole group first, to master it before mixing. Add a timer to create a bit of friendly competition between players.', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 25, 'One more pass', false, 2, ARRAY['U16','U18','Seniors']::text[], ARRAY['Passing','Shooting']::text[], ARRAY['Balls']::text[], ARRAY['Ball sharing','Ball movement']::text[], ARRAY['Quick ball movement','Open shot']::text[], 'Three or four players take up the usual perimeter spots. One player (or the coach) makes the first pass. As soon as the receiver has the ball, the next player calls out "one more!" to signal they''re open, and immediately receives the pass. The third player does the same, and shoots after this last pass. The drill then rotates by changing the starting spot.', 'Add a dribble before the shot for the final receiver. Introduce a passive defender closing a passing lane to force a real read.', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 26, 'Shooting star', false, 2, ARRAY['U14','U16']::text[], ARRAY['Passing','Fast break']::text[], ARRAY['Balls']::text[], ARRAY['Pass on the move','Speed']::text[], ARRAY['Fast passing','Lane alignment']::text[], 'Five columns of players fan out across the full width of the court. The ball moves from one column to the next in a fixed order while all players sprint toward the opposing basket. Each passer follows their pass to join the next column. The drill ends with a shot on the run by the final receiver.', 'Change the order the ball moves in so players can''t anticipate too much. Time each full court crossing.', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 27, 'The 10 golden passes', false, 3, ARRAY['U16','U18','Seniors']::text[], ARRAY['Passing','Defense']::text[], '{}', ARRAY['Turnover prevention','Spacing']::text[], ARRAY['Turnover prevention','Occupying space']::text[], 'Half court, two teams of 3 play against each other. The offense must complete 10 consecutive passes without traveling, without a double dribble, and without a turnover, without even trying to score. The offense must pass, cut, dribble, set screens, and space well to get there. If the offense completes its 10 passes, it doesn''t have to defend the next round; otherwise, roles swap.', 'Reduce to 7 passes for younger groups. Allow a free shot after 10 successful passes, as a reward.', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 28, 'Catch and go', false, 1, ARRAY['U12','U14']::text[], ARRAY['Shooting','Passing']::text[], ARRAY['Balls']::text[], ARRAY['Catch on the move','Triple threat']::text[], ARRAY['Catch on the move','Triple threat']::text[], 'Two columns of players face each other on either side of the basket, one holding balls. The first player in the ball-less column takes a small step toward the middle to receive a short pass from the first player in the other column, then shoots immediately. Each player retrieves their ball or joins the opposite column, depending on how the coach organizes it.', 'Gradually lengthen the running distance before the catch. Add a shot fake before actually shooting.', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 29, 'Four-spot shooting tour', false, 2, ARRAY['U16','U18','Seniors']::text[], ARRAY['Shooting']::text[], ARRAY['Balls']::text[], ARRAY['Repetition','Shot variety']::text[], ARRAY['Shot variety','Sustained pace']::text[], 'Players work in pairs, one shooter and one rebounder/passer, at one basket. At each spot around the three-point line, the shooter runs through: a three-point shot, a jump shot off a shot fake, a catch-and-shoot, then a layup drive. The partner rebounds and passes back each time. After the full series at one spot, the two players swap roles, then move to the next spot.', 'Reduce to 2 types of shots for younger players. Add a points target (e.g. 3 pts per made three) to create some friendly competition between pairs.', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 30, 'Drive and kick', false, 3, ARRAY['U18','Seniors']::text[], ARRAY['Shooting','1v1']::text[], ARRAY['Balls']::text[], ARRAY['Drive and kick','Reading the defense']::text[], ARRAY['Drive and kick','Quick relocation']::text[], 'The ball handler starts at the wing with a ball, drives into the paint as if looking to score, then kicks the ball out to a teammate who has relocated to the three-point line. After the pass, the first player sprints to the opposite wing to be available in turn. The receiver must also make themselves available by sliding along the arc or coming back to the corner.', 'Add a live defender on the ball handler to make the read realistic. Go straight into a 1-on-1 if the kick-out pass isn''t available.', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 31, 'Pass, cut, duel', false, 3, ARRAY['U16','U18']::text[], ARRAY['1v1','Passing']::text[], '{}', ARRAY['Getting open','Duel']::text[], ARRAY['Pass and cut','1-on-1']::text[], 'Three players per quarter of the court. The ball handler passes to the wing and immediately goes to defend them. The wing passes to a third player then makes a simple V-cut to get open again for the ball, while their defender follows. As soon as they receive the ball again, they play 1-on-1 against that defender. Roles then rotate among the three players.', 'Replace the V-cut with an L-cut or a backdoor cut to vary the paths. Let the passer choose when to pass, to develop the receiver''s constant availability.', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 32, 'Three-man weave', false, 2, ARRAY['U14','U16']::text[], ARRAY['Fast break','Passing']::text[], ARRAY['Balls']::text[], ARRAY['Transition','Numbers advantage']::text[], ARRAY['Weave movement','2-on-1 decision']::text[], 'Three players run up the court weaving their movement: each passes the ball then follows their pass, running behind the receiver to relocate on the opposite side. The player who makes the third pass of the weave becomes the defender, and the other two finish the play in a 2-on-1 toward the basket.', 'Run the drill full-court, down and back, to add conditioning. Set a maximum number of dribbles to force a quick decision in the 2-on-1.', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 33, 'The endless chain', false, 1, ARRAY['U12','U14']::text[], ARRAY['Fast break']::text[], ARRAY['Balls']::text[], ARRAY['Transition','Habits']::text[], ARRAY['Transition habits']::text[], 'Three columns of players under each basket, unopposed at first, to establish the paths and timing of fast-break passes. The middle ball handler starts the play, the two wings sprint out toward the sidelines, the ball moves until finishing at the basket. The next group starts as soon as the previous one finishes its shot.', 'Add a defender who comes back from the baseline after a short delay, to gradually move to a fast break with light opposition.', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 34, 'Close and bounce', false, 2, ARRAY['U16','U18','Seniors']::text[], ARRAY['Defense']::text[], '{}', ARRAY['Close-out','Defensive footwork']::text[], ARRAY['Close-out','Low stance']::text[], 'A player starts from the middle of the paint and sprints to close the distance ("close-out") on a teammate positioned outside with a ball, using short shuffle steps with hands up to contest a potential shot without jumping at it. Once there, they must be ready to react if the attacker drives either way. Roles swap after each rep.', 'The attacking partner can freely choose to shoot or drive left or right, forcing the defender to truly read the situation instead of anticipating.', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 35, 'Wake-up relay', false, 1, ARRAY['All ages']::text[], ARRAY['Warm-up','Dribble']::text[], ARRAY['Balls','Marker cones']::text[], ARRAY['Getting going','Fun']::text[], ARRAY['Dynamic warm-up']::text[], 'Two teams in a relay, each player slaloms dribbling through a row of markers before running back to tag the next player''s hand. A different constraint can be set each round: right hand only, left hand only, hand change at every marker. The team that finishes all its turns first wins the round.', 'End each turn with a shot to add a technical goal on top of speed. Reduce the marker spacing for more experienced groups.', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 36, 'The dribbling flag thief', false, 1, ARRAY['U10','U12']::text[], ARRAY['Fun','Dribble']::text[], ARRAY['Balls','Bibs']::text[], ARRAY['Game','Ball protection']::text[], ARRAY['Ball protection','Awareness']::text[], 'Each player dribbles at all times and tucks a small flag or bib into the back of their shorts. On the signal, everyone tries to steal as many flags as possible from others, without ever stopping their own dribble or losing their own flag. A player can grant themselves one-time temporary immunity per round by sitting on the floor while continuing to dribble.', 'Shrink the play area to increase density and difficulty. Count flags stolen per player to name a winner at the end of each round.', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 37, 'Red light, green light with dribble', false, 1, ARRAY['U8','U10']::text[], ARRAY['Fun','Dribble']::text[], ARRAY['Balls']::text[], ARRAY['Game','Stops']::text[], ARRAY['Clean stop','Ball protection']::text[], 'One ball-less player faces a wall (or has their back to the group) and calls out loud "Red light, green light!" before turning around. Meanwhile, all other players dribble toward them. As soon as they turn, everyone must be completely still, ball included (no visible bounce): any player caught moving goes back to the start. The first player to reach the caller wins and takes their place for the next round.', 'Require a different dribbling hand each round. Only allow small shuffle steps in addition to the dribble, to work on coordination.', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 38, 'The wolf and the sheep', false, 1, ARRAY['U8','U10']::text[], ARRAY['Fun','Dribble']::text[], ARRAY['Balls']::text[], ARRAY['Game','Introduction']::text[], ARRAY['Head up','Simple game']::text[], 'Within a marked area, each child dribbles their own ball. One chosen child is "the wolf" and must tag one of the "sheep" while staying in dribble themselves. As soon as a sheep is tagged, it becomes the wolf in turn and the old wolf becomes a sheep again. For older kids, you can add that a child who loses their ball, double-dribbles, or leaves the court shares the same fate as a tagged child.', 'Name 2 wolves at once to speed up the game with a large group. Shrink the play area to increase difficulty as the kids improve.', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 39, 'The shooter''s puzzle', false, 1, ARRAY['U10','U12']::text[], ARRAY['Shooting','Fun']::text[], ARRAY['Cones','Balls']::text[], ARRAY['Game','Motivation']::text[], ARRAY['Repeating the motion','Technique over score']::text[], 'Two teams compete at two baskets. Several small cones mark different shooting spots, with a puzzle piece hidden behind each one. On the signal, a player from each team dribbles to a cone, shoots, and if they score AND their shooting form is judged correct by the coach, they can bring back the puzzle piece and place it on their team''s board before setting off again. If they fail (missed shot or incorrect form), the player comes back without a piece. The first team to complete its puzzle wins.', 'Adjust the difficulty of the shooting spots to the level. Have other kids judge the form in turn, to give them responsibility.', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 40, 'The rainbow hunt', false, 1, ARRAY['U8','U10']::text[], ARRAY['Passing','Fun']::text[], ARRAY['Balls']::text[], ARRAY['Game','Reactivity']::text[], ARRAY['Fast team passing','Visual cues']::text[], 'Scatter shapes of different colors around the gym (circles, squares, triangles in several colors). Form teams of 2 players, each with a ball. The coach calls out a shape and a color (for example "yellow circle"). The first team to bring their ball to the announced shape and color, following the technical instructions given (correct passes, no illegal dribble, etc.), scores a point.', 'Add complexity by calling out a sequence of several shapes to reach in order. Require a specific type of pass (two-hand pass, bounce pass) depending on the shape called.', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 41, 'The champion''s course', false, 2, ARRAY['U10','U12']::text[], ARRAY['Dribble','Shooting']::text[], ARRAY['Cones','Balls','Rings']::text[], ARRAY['Coordination','Course']::text[], ARRAY['Technical sequence','Coordination']::text[], 'A full dribbling course: slalom between markers, then at center court touch the ground at two markers (right hand then left hand) without stopping the dribble, another slalom, a shot from a small cone, grabbing the rebound, a sequence of low dribble then hip-height dribble to a large cone, a full loop around rings placed on the floor, then another slalom and a final shot before starting the course again from the beginning.', 'Turn it into a card game: for every made basket, the child can take a playing card and keep it; whoever has the most at the end of the time wins.', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 42, '45 seconds of pressure shooting', false, 3, ARRAY['U18','U20','Seniors']::text[], ARRAY['Shooting','Competition']::text[], ARRAY['Balls']::text[], ARRAY['Time pressure','Competition']::text[], ARRAY['Effectiveness under pressure','Speed of execution']::text[], 'A player takes shots as fast as possible from spots chosen by the coach. Each missed shot removes a point, each made shot adds one. The drill ends as soon as the player reaches 11 points (whether by scoring a lot or missing a lot), which creates real pressure to catch up after a run of misses.', 'Turn it into a challenge between two players at two neighboring baskets, first to 11 wins. Require movement (lateral run, sprint) between each shot to add fatigue.', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 43, 'Duel to 10', false, 2, ARRAY['U16','U18','Seniors']::text[], ARRAY['Shooting','Competition']::text[], ARRAY['Balls']::text[], ARRAY['Offensive rebound','Cooperation']::text[], ARRAY['Offensive rebound','Motivation']::text[], 'Two players, a shooter and a rebounder, combine their points together until reaching 10: each basket by the shooter is worth one point, and each offensive rebound put back by the rebounder before the ball touches the ground is also worth one point for the team. The two players then swap roles.', 'Run a competition between two pairs at two baskets, first pair to 10 wins. Require the rebounder to finish with one hand only, to work on a quick finish.', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 44, 'My shot, my rules', false, 3, ARRAY['U18','U20','Seniors']::text[], ARRAY['Shooting','1v1']::text[], ARRAY['Balls']::text[], ARRAY['Offensive autonomy','Reading the defense']::text[], ARRAY['Offensive autonomy','Few dribbles']::text[], 'The player receives the ball from different spots (wing, top of the key, mid-post) against a defender, and must look to shoot using as few dribbles as possible, without looking for a full drive to the rim. If the situation doesn''t allow a shot, they pass to the coach or a teammate and keep moving without the ball to relocate and ask for it again.', 'Explicitly limit to 1 or 2 dribbles max to force a quick decision. Add a passive defender, then progressively more active, depending on the player''s level.', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 45, 'Shooting through traffic', false, 3, ARRAY['U16','U18']::text[], ARRAY['Shooting','Defense']::text[], ARRAY['Other']::text[], ARRAY['Contact','Concentration']::text[], ARRAY['Shooting through contact','Concentration']::text[], 'The shooter passes to themselves, takes a dribble, then stops to shoot, while one or two defenders try to disrupt the shot by pushing a large cushion or soft mat against them (never dangerous direct contact). Start with a single cushion placed in front, then behind, then both at once, to gradually get the player used to shooting while keeping their balance and focus on the rim despite the disruption.', 'Use only one level of difficulty at a time before combining them. Emphasize protecting the ball with the free arm after the dribble, before each shot.', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 46, 'The numbers-advantage staircase', false, 2, ARRAY['U12','U14']::text[], ARRAY['2v2','Fast break']::text[], '{}', ARRAY['Progressive teaching','Numbers advantage']::text[], ARRAY['Progressive numbers advantage','Collective reading']::text[], 'This session follows a step-by-step progression, only moving to the next step once the group has mastered the previous one: first a simple 2-on-1, then a 2-on-1 with an extra player joining the play afterward, then a 2-on-2, and finally a 3-on-2. Each step keeps the same basic principles (finding the open space, making the right pass at the right time) with an increasing level of opposition.', 'Adjust the time spent on each step based on the group''s progress as observed by the coach. End the session with a 3-on-3 as a complete game form for more experienced players.', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 47, 'Defensive star', false, 2, ARRAY['U16','U18','Seniors']::text[], ARRAY['Defense']::text[], '{}', ARRAY['Communication','Positioning']::text[], ARRAY['Defensive positions','Communication']::text[], 'Four attackers spread out around the three-point line (two in line with the free-throw line, two at the wings). The ball moves from one attacker to another while the defenders adjust their position on every pass: the one one pass away from the ball stays in a deny position with a hand in the passing lane; the one two passes away drops to help at one-third of the way; the one three passes away drops to help halfway. Each player must call out their position loudly ("Ball!", "Deny!", "Help!") on every pass. At first, the offense is asked to wait for the coach''s signal before each pass to properly check positions; once the habits are set, the drill becomes live with a maximum of 3 dribbles allowed for the offense.', 'Move to a "live" version with real opposition once the positions are well understood. Remove the dribble limit for more experienced groups.', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 48, 'Reinforcements arriving', false, 2, ARRAY['U16','U18']::text[], ARRAY['Fast break']::text[], ARRAY['Balls']::text[], ARRAY['Transition','Numbers advantage']::text[], ARRAY['Numbers advantage','Speed of decision']::text[], 'Two teams line up on the sides at half court, with one defender from each team already positioned at their own basket. Two attackers start with a ball just past the half-court line and attack the first defender 2-on-1, trying to get them to commit to one of the two. As soon as the attackers cross half court, a second defender sprints from the center circle to join their teammate, turning the situation into a 2-on-2 before the play ends.', 'Limit the number of dribbles allowed to force a quick decision. Rotate roles so every player goes through all 4 positions (both attackers and both defenders).', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 49, 'Rebound, run, repeat', false, 2, ARRAY['U14','U16','U18']::text[], ARRAY['Fast break','Defense']::text[], ARRAY['Balls']::text[], ARRAY['Defensive rebound','Transition']::text[], ARRAY['Rebound then transition','No dead time']::text[], 'Two attackers with a ball start from half court against two defenders already in place. After the shot, both defenders must box out and battle the attackers for the rebound. Once the play ends (basket made or rebound secured), the attackers leave the court and a new pair of defenders comes in: the previous pair of defenders becomes the new pair of attackers for the next play. The drill runs continuously this way, each pair alternating between offense and defense.', 'Switch to a 3-on-2 format to give the offense a clear numbers advantage and focus on reading the advantage. Track points scored by each pair over several rounds to add stakes.', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 50, 'Pivot and escape', false, 2, ARRAY['U14','U16']::text[], ARRAY['1v1','Dribble']::text[], ARRAY['Balls']::text[], ARRAY['Triple threat','Protection']::text[], ARRAY['Triple threat','Escape pivot']::text[], 'Facing a defender, the attacker receives the ball in triple threat and must protect it with pivots and "rip-through" moves (ball swept sharply from one knee to the opposite shoulder) without being allowed to dribble for 4 to 5 seconds. On the signal, the attacker uses one of their pivots to create space from the defender and drives to the basket to finish the play.', 'Vary the protection time before the start signal. Allow the defender to apply increasing pressure over repetitions.', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 51, 'Pass and go', false, 1, ARRAY['U12','U14']::text[], ARRAY['Passing','Shooting']::text[], ARRAY['Balls']::text[], ARRAY['Pass and run','Habits']::text[], ARRAY['Pass and run','Cutting reflex']::text[], 'Two players start from half court, one with a ball. The ball handler passes to their partner then immediately sprints toward the basket, cutting in front of them ("give-and-go"). As soon as the partner sees the runner start, they pass the ball back so the runner can finish with a layup. Roles swap on each turn through the line.', 'Add a passive defender on the runner to introduce slight opposition. Run the drill full-court to add speed and conditioning.', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 52, 'The "Coach says" game', false, 1, ARRAY['U8','U10','U12']::text[], ARRAY['Warm-up','Fun']::text[], '{}', ARRAY['Attention','Listening']::text[], ARRAY['Listening','Reactivity']::text[], 'Like the "Simon says" game, players only perform the coach''s instruction (jump on one foot, touch the ground, run in place, etc.) if it''s preceded by "Coach says." If a player reacts to an instruction that wasn''t preceded by that phrase, they must sit down and wait for the round to end. The last player still standing wins that round.', 'Replace the general actions with basketball-specific moves (dribble, pivot, imaginary shot) to combine a fun warm-up with a technical reminder. Run short, repeated rounds to keep everyone engaged.', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 53, 'Defensive chase', false, 2, ARRAY['U16','U18','Seniors']::text[], ARRAY['Defense','Fast break']::text[], ARRAY['Balls']::text[], ARRAY['Defensive transition','Recovery']::text[], ARRAY['Defensive recovery','Managing space']::text[], 'An attacker drives from half court while a defender, initially trailing, must sprint to get back in front of them. The defender should not try to directly grab the ball but rather slow the attacker''s progress, read the direction of their movement, and take up as much space as possible with their arms once back in front of them.', 'Vary the defender''s starting point to simulate different degrees of being behind. Move straight into a full 1-on-1 once the defender has recovered.', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 54, 'The warning call', false, 3, ARRAY['U18','Seniors']::text[], ARRAY['Defense','Fast break']::text[], ARRAY['Balls']::text[], ARRAY['Defensive communication','Three-quarter court']::text[], ARRAY['Defensive communication','Fake']::text[], 'Over three-quarters of the court, two attackers break out against a single defender, with a second defender who must join the play after a short delay. The lone defender must communicate, fake an attempt at the ball handler to slow them down, without ever getting fully beaten before their teammate arrives.', 'Run the drill back and forth, without resetting, to chain several reps directly. Explicitly forbid unsporting fouls so defenders learn the right solutions instead of a systematic foul.', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 55, 'Fighting through the screen', false, 3, ARRAY['U16','U18']::text[], ARRAY['Defense']::text[], '{}', ARRAY['Screens','Individual defense']::text[], ARRAY['Fighting through a screen','Contact with the attacker']::text[], 'An attacker uses a screen set by a teammate to get open, while a single defender must fight through the screen to stay with them (the screener is not defended in this simplified version). The defender must maintain forearm/hip contact with their attacker, create enough space to slide between the attacker and the screener, and get through the screen alongside them rather than going around it widely.', 'Add a second defender on the screener once the individual movement is mastered, to introduce real 2-player defensive teamwork. Vary the type of screen (face-up, cross, down) to work different angles to defend.', '{}'::jsonb, true),
  ('00000000-0000-0000-0000-000000000001', 99, 'Old', false, 1, '{}', '{}', '{}', '{}', '{}', null, null, '{}'::jsonb, true);

